const groupCourses = computed(() => courses.filter(c => c.group === activeGroup.value))

const select = (index) => { active.value=index; activeGroup.value=courses[index].group; document.querySelector('#experience')?.scrollIntoView({behavior:'smooth'}) }
const selectGroup = (group) => { activeGroup.value=group; requestAnimationFrame(()=>document.querySelector('#trainings')?.scrollIntoView({behavior:'smooth'})) }
const handleScroll = () => { progress.value = window.scrollY / (document.documentElement.scrollHeight - innerHeight) * 100 }

onMounted(() => {
  const el=canvas.value, ctx=el.getContext('2d'); let points=[]; const pointer={x:innerWidth*.65,y:innerHeight*.4}
  const resize=()=>{el.width=innerWidth*devicePixelRatio;el.height=innerHeight*devicePixelRatio;el.style.width=`${innerWidth}px`;el.style.height=`${innerHeight}px`;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);points=Array.from({length:54},()=>({x:Math.random()*innerWidth,y:Math.random()*innerHeight,vx:(Math.random()-.5)*.16,vy:(Math.random()-.5)*.16,r:Math.random()*1.6+.4}))}
  const move=e=>{pointer.x=e.clientX;pointer.y=e.clientY}
  const draw=()=>{ctx.clearRect(0,0,innerWidth,innerHeight);points.forEach((p,i)=>{p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>innerWidth)p.vx*=-1;if(p.y<0||p.y>innerHeight)p.vy*=-1;for(let j=i+1;j<points.length;j++){const q=points[j],d=Math.hypot(p.x-q.x,p.y-q.y);if(d<150){ctx.strokeStyle=`rgba(67,142,255,${(1-d/150)*.12})`;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()}}const d=Math.hypot(p.x-pointer.x,p.y-pointer.y);ctx.fillStyle=d<220?'rgba(111,228,255,.7)':'rgba(76,126,190,.2)';ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()});frame=requestAnimationFrame(draw)}
  resize();draw();addEventListener('resize',resize);addEventListener('pointermove',move);addEventListener('scroll',handleScroll)
  onBeforeUnmount(()=>{cancelAnimationFrame(frame);removeEventListener('resize',resize);removeEventListener('pointermove',move);removeEventListener('scroll',handleScroll)})
})
