        <g v-else-if="group.code==='03'"><path d="M27 78V52h20v26M61 78V39h20v39M95 78V26h20v52M129 78V14h20v64M22 78h132"/><path d="m30 37 34-13 33 4 45-20"/></g>
        <g v-else-if="group.code==='04'"><circle cx="90" cy="28" r="13"/><circle cx="43" cy="51" r="10"/><circle cx="137" cy="51" r="10"/><path d="M68 85c2-18 9-29 22-29s20 11 22 29M25 84c2-14 8-23 18-23 9 0 15 7 18 18M119 79c3-11 9-18 18-18 10 0 16 9 18 23"/></g>
