        <g v-else><path d="M90 86C54 77 42 50 56 22c31 2 55 17 58 44-1 12-8 19-24 20Z"/><path d="M61 30c13 17 23 33 29 56M94 47c13-7 24-9 35-5M105 70c16 2 29-2 38-12"/><circle cx="143" cy="58" r="7"/></g>
