      <section id="trainings" class="training-browser"><header><div><span class="chapter">SZKOLENIA / {{activeGroup}}</span><h2>Wybierz program.</h2></div><button @click="document.querySelector('#calendar')?.scrollIntoView({behavior:'smooth'})">ZMIEŃ KATEGORIĘ ↑</button></header><div><button v-for="course in groupCourses" :key="course.title" :style="{'--accent':course.color}" @click="select(courses.indexOf(course))"><span class="training-code">{{course.code}}</span><div><small>{{course.category}}</small><h3>{{course.title}}</h3><p>{{course.lead}}</p></div><em>{{course.scope}}<br>{{course.format}}</em><i>↗</i></button></div></section>

      <section id="experience" class="program-scene"><nav class="program-switcher" aria-label="Przełącz program szkoleniowy"><button v-for="course in groupCourses" :key="course.title" :class="{active:courses.indexOf(course)===active}" :style="{'--accent':course.color}" @click="active=courses.indexOf(course)"><span>{{course.code}}</span><b>{{course.title}}</b></button></nav><header><span class="chapter">WYBRANY PROGRAM</span><p>{{current.category}}</p></header><div class="program-title"><div class="program-date"><b>{{current.code}}</b><span>{{current.group}}</span></div><h2>{{current.title}}</h2><p>{{current.description}}</p></div><div class="program-data"><div><span>PROWADZENIE</span><b>{{current.trainer}}</b><small>{{current.role}}</small></div><div><span>FORMA</span><b>{{current.format}}</b><small>na żywo z prowadzącym</small></div><div><span>ZAKRES</span><b>{{current.scope}}</b><small>dopasujemy do poziomu grupy</small></div></div><ol><li v-for="point in current.points" :key="point"><span>{{point}}</span></li></ol><aside><div><span>PROGRAM DLA OSÓB I FIRM</span><strong>Chcesz zrealizować to szkolenie?</strong><p>Ustalimy termin, formę, poziom zaawansowania oraz zakres odpowiadający Twojej grupie.</p></div><button class="program-inquiry" @click="inquirySent=false;inquiryOpen=true">ZAPYTAJ O TERMIN I WYCENĘ <b>↗</b></button></aside></section>

      <section id="method" class="method-scene"><div class="method-statement"><span class="chapter">JAK PRACUJEMY</span><h2>Nie oglądasz.<br><em>Uczestniczysz.</em></h2><p>Każdy program ma jasny cel, przejrzystą agendę i konkretne rezultaty. Możemy zmienić zakres, poziom oraz przykłady tak, aby szkolenie odpowiadało sytuacji Twojej organizacji.</p></div><div class="method-path"><article><b>AGENDA</b><span>przed szkoleniem</span><h3>Wiesz dokładnie, czego się nauczysz</h3><p>Otrzymujesz czytelną agendę, cele modułów i informacje organizacyjne. Przy szkoleniu zamkniętym wcześniej zbieramy potrzeby zespołu.</p></article><article><b>NARZĘDZIA</b><span>online i na sali</span><h3>Technologia wspiera aktywną pracę</h3><p>Spotkania online prowadzimy na Microsoft Teams lub Zoom. Wykorzystujemy udostępnianie ekranu, pokoje warsztatowe, ankiety, tablice i pliki robocze.</p></article><article><b>PRAKTYKA</b><span>w trakcie</span><h3>Pracujesz na przykładach i pytaniach</h3><p>Prowadzący łączy omówienie tematu z ćwiczeniami, analizą przypadków i dyskusją. Uczestnicy mogą konsultować własne sytuacje.</p></article><article><b>DOPASOWANIE</b><span>dla Twojej firmy</span><h3>Program może powstać wokół potrzeb klienta</h3><p>Dostosujemy czas, poziom zaawansowania, branżowe przykłady i materiały. Po szkoleniu uczestnicy otrzymują materiały, narzędzia oraz certyfikat.</p></article></div></section>

      <section id="contact" class="contact-scene"><div><span class="chapter">KONTAKT</span><h2>Porozmawiajmy<br>o wiedzy.</h2><p>Nie potrzebujesz gotowego tytułu. Opisz zmianę, ryzyko albo kompetencję. Przygotujemy propozycję tematu, formy i zakresu.</p><div class="direct-contact"><a href="mailto:kontakt@imperialacademy.pl"><span>E-MAIL</span><b>kontakt@imperialacademy.pl</b></a><a href="tel:+48220000000"><span>TELEFON</span><b>+48 22 000 00 00</b></a><p><span>GODZINY KONTAKTU</span><b>pon.—pt. / 8:00—16:00</b></p></div></div><form @submit.prevent="sent=true"><template v-if="!sent"><header class="form-intro"><span>FORMULARZ KONTAKTOWY</span><h3>Napisz do nas</h3><p>Uzupełnij pola, a przygotujemy odpowiedź dopasowaną do Twojej sytuacji.</p></header><label><b>Imię i nazwisko</b><input required placeholder="np. Anna Kowalska"/></label><label><b>E-mail służbowy</b><input required type="email" placeholder="anna@firma.pl"/></label><label><b>Firma lub instytucja</b><input placeholder="Nazwa organizacji"/></label><label><b>Jakiego szkolenia potrzebujesz?</b><textarea required rows="4" placeholder="Opisz temat, problem, liczbę uczestników lub preferowaną formę..."></textarea></label><button>WYŚLIJ ZAPYTANIE <b>↗</b></button><small>Odpowiemy w ciągu jednego dnia roboczego.</small></template><div v-else class="sent"><b>✓</b><h3>Wiadomość odebrana.</h3><p>Wrócimy z propozycją w ciągu jednego dnia roboczego.</p></div></form></section>
    </main>
    <Teleport to="body"><div v-if="inquiryOpen" class="inquiry-modal" role="dialog" aria-modal="true" aria-labelledby="inquiry-title" @click.self="inquiryOpen=false"><div class="inquiry-window"><button class="modal-close" aria-label="Zamknij" @click="inquiryOpen=false">×</button><template v-if="!inquirySent"><header><span>ZAPYTANIE O KONKRETNE SZKOLENIE</span><h2 id="inquiry-title">{{current.title}}</h2><p>{{current.category}}</p></header><div class="selected-summary"><div><span>FORMA</span><b>{{current.format}}</b></div><div><span>ZAKRES</span><b>{{current.scope}}</b></div><div><span>PROWADZENIE</span><b>{{current.trainer}}</b></div></div><form @submit.prevent="inquirySent=true"><div class="modal-row"><label><b>Imię i nazwisko</b><input required placeholder="Anna Kowalska"/></label><label><b>E-mail służbowy</b><input required type="email" placeholder="anna@firma.pl"/></label></div><div class="modal-row"><label><b>Firma lub instytucja</b><input placeholder="Nazwa organizacji"/></label><label><b>Liczba uczestników</b><input type="number" min="1" placeholder="np. 12"/></label></div><div class="modal-row"><label><b>Preferowana forma</b><select><option>Online</option><option>Stacjonarnie w naszej firmie</option><option>Stacjonarnie — potrzebujemy sali</option><option>Do ustalenia</option></select></label><label><b>Preferowany termin</b><input type="text" placeholder="np. październik 2026"/></label></div><label><b>Dodatkowe oczekiwania</b><textarea rows="3" placeholder="Poziom grupy, zagadnienia do uwzględnienia, branża..."></textarea></label><button type="submit">WYŚLIJ ZAPYTANIE O WYCENĘ <b>→</b></button></form></template><div v-else class="inquiry-success"><b>✓</b><h2>Zapytanie zapisane</h2><p>Wiemy, że interesuje Cię szkolenie „{{current.title}}”. Wrócimy z propozycją terminu i wyceną.</p><button @click="inquiryOpen=false">ZAMKNIJ</button></div></div></div></Teleport>
